// The "Two-Round Event Flow" section under the Upcoming card (hackathon only).
// You do not edit this file. The words, and the on/off switch (SHOW_FLOW), are in site/upcomingConfig.js.
import { Icon } from './Icons';
import { Reveal, useInView } from './ui';
import { TYPE } from './teaserCore';
import { FLOW, SHOW_FLOW } from './upcomingConfig';
import './EventFlow.css';

// one colour for each phase of Round 2 (the same four colours as the stats on the home page)
const PHASE_COLORS = ['#4285f4', '#34a853', '#fbbc05', '#ea4335'];

const num = (n) => String(Math.round(n * 10) / 10);
const hrs = (n) => `${num(n)} ${n === 1 ? 'hr' : 'hrs'}`;

function Round1({ r }) {
  return (
    <Reveal as="article" className="s-fl s-fl-1" aria-label={`${r.tag}: ${r.name}`}>
      <span className="s-fl-ghost" aria-hidden="true">1</span>
      <header className="s-fl-top">
        <span className="s-fl-tag"><b>{r.tag}</b><i /><span><Icon.Globe size={13} /> {r.where}</span></span>
        <h3 className="s-fl-name">{r.name}</h3>
        {r.intro && <p className="s-fl-intro">{r.intro}</p>}
      </header>

      <ol className="s-fl-steps">
        {r.steps.map((s, i) => (
          <li key={s.title}>
            <span className="s-fl-n" aria-hidden="true">{i + 1}</span>
            <div className="s-fl-sb">
              <h4>{s.title}</h4>
              <p>{s.desc}</p>
              {s.tools && (
                <ul className="s-fl-tools" aria-label="Tools you can use">
                  {s.tools.map((t) => <li key={t}>{t}</li>)}
                </ul>
              )}
              {s.levels && (
                <div className="s-fl-levels">
                  {s.levels.map((l) => (
                    <div key={l.tag} className={`s-fl-lv ${l.bonus ? 'is-bonus' : ''}`}>
                      <span className="s-fl-lv-t">
                        {l.bonus ? <Icon.Sparkles size={13} /> : <Icon.Check size={13} />} {l.tag}
                        <em>{l.note}</em>
                      </span>
                      <p>{l.desc}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </li>
        ))}
      </ol>
    </Reveal>
  );
}

function Round2({ r }) {
  const [barRef, barIn] = useInView(0.3);
  const total = r.phases[r.phases.length - 1].to || 1;
  const at = (h) => `${(h / total) * 100}%`;
  const ticks = [0, ...r.phases.map((p) => p.to)];
  const summary = r.phases.map((p, i) => `Phase ${i + 1}, hours ${num(p.from)} to ${num(p.to)}: ${p.title}`).join('. ');

  return (
    <Reveal as="article" className="s-fl s-fl-2" delay={120} aria-label={`${r.tag}: ${r.name}`}>
      <span className="s-fl-ghost" aria-hidden="true">2</span>
      <header className="s-fl-top">
        <span className="s-fl-tag"><b>{r.tag}</b><i /><span><Icon.Clock size={13} /> {r.where}</span></span>
        <h3 className="s-fl-name">{r.name}</h3>
        {r.intro && <p className="s-fl-intro">{r.intro}</p>}
        {r.venue && <p className="s-fl-venue"><Icon.MapPin size={15} /> {r.venue}</p>}
      </header>

      <div className="s-fl-bar" ref={barRef} role="img" aria-label={summary}>
        <div className="s-fl-flags" aria-hidden="true">
          {r.phases.filter((p) => p.check).map((p) => (
            <span key={p.check} className="s-fl-flag" style={{ left: at(p.to) }}><i /></span>
          ))}
        </div>
        <div className={`s-fl-track ${barIn ? 'in' : ''}`} aria-hidden="true">
          {r.phases.map((p, i) => (
            <i key={p.title} style={{ flexGrow: p.to - p.from, '--c': PHASE_COLORS[i % PHASE_COLORS.length], '--i': i }} />
          ))}
        </div>
        <div className="s-fl-ticks" aria-hidden="true">
          {ticks.map((h, i) => (
            <span key={`${h}-${i}`} className={i === 0 ? 'is-first' : i === ticks.length - 1 ? 'is-last' : ''} style={{ left: at(h) }}>{num(h)}h</span>
          ))}
        </div>
      </div>

      <ol className="s-fl-phases">
        {r.phases.map((p, i) => (
          <li key={p.title} style={{ '--c': PHASE_COLORS[i % PHASE_COLORS.length] }}>
            <span className="s-fl-ph"><i aria-hidden="true" />Phase {i + 1}</span>
            <div className="s-fl-pb">
              <h4>{p.title}</h4>
              <span className="s-fl-hrs">Hours {num(p.from)} to {num(p.to)}{p.from > 0 ? ` · ${hrs(p.to - p.from)}` : ''}</span>
              {p.check && <span className="s-fl-check"><Icon.Users size={13} /> {p.check}</span>}
            </div>
          </li>
        ))}
      </ol>
    </Reveal>
  );
}

export default function EventFlow() {
  if (!SHOW_FLOW || TYPE !== 'hackathon' || !FLOW || !FLOW.r1 || !FLOW.r2) return null;
  const { r1, r2, link } = FLOW;
  return (
    <section className="s-flow" aria-labelledby="s-flow-h">
      <Reveal className="s-flow-head">
        {FLOW.eyebrow && <span className="s-eyebrow">{FLOW.eyebrow}</span>}
        <h2 id="s-flow-h" className="s-flow-h">{FLOW.title}</h2>
        {FLOW.sub && <p className="s-flow-sub">{FLOW.sub}</p>}
      </Reveal>

      <div className="s-flow-grid">
        <Round1 r={r1} />
        {link && (
          <Reveal className="s-fl-link" delay={60}>
            <i aria-hidden="true" />
            <div className="s-fl-badge">
              <small>{link.top}</small>
              <b>{link.big}</b>
            </div>
            <span className="s-fl-linklabel">{link.label} <Icon.ArrowRight size={14} /></span>
            <i aria-hidden="true" />
          </Reveal>
        )}
        <Round2 r={r2} />
      </div>
    </section>
  );
}
